#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"#include "..\Resource.h"#define	LARGE_ARROW_UP		"0xc02A"#define	LARGE_ARROW_DOWN	"0xc02B"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  char name[64];  int    nCode;  bool   bReal;  bool   bSelect;  int nPressedCode;  bool bGrey;  bool bBlackUpWithLamp;  bool bGreen;  bool bRed;  } Queue_SensKbd;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~bool ProcessOnMouseDown(char *szCode){	if ( !_stricmp(szCode, LARGE_ARROW_UP) || !_stricmp(szCode, LARGE_ARROW_DOWN) )		return true;	return false;}int PressSensKbd(DefinePress)  {  Queue_SensKbd* p = (Queue_SensKbd*)s;  if ( *p->name == '.' || *p->name == '\0'  ) return 1;  bool bProcessOnDown = (p->btSendType == QUEUE_SENSKEYBOARD) ? ProcessOnMouseDown (p->name) : false;  static char szSensKbd[256];  p->nPressedCode=nCode;  static int a;  if ( nCode == 0 )    {    a = 0;    if ( p->bReal )      {      lstrcpy( szSensKbd, p->name );      ::PostMsg( q.hWnd, p->btSendType, (LPARAM)szSensKbd);      }	::InvalidateRect( q.hWnd, NULL, FALSE );	::MessageBeep(-1);	if ( bProcessOnDown && !p->bReal )	{		lstrcpy( szSensKbd, p->name );		::PostMsg( q.hWnd, p->btSendType, (LPARAM)szSensKbd);	}    return 0;    }    a++;    if ( nCode == 1 ) if ( a < 6 || a % 3 ) return 0;	if (( nCode == 1 )||( nCode == 2 ))	::InvalidateRect( q.hWnd, NULL, FALSE );  //  if ( point.x == -1 && point.y == -1 )    {    if ( ( p->nCode & 0xff ) != nCode )      return 1;    }  else  if ( !::PtInRect( &p->mRect, point ) )    return 0;  //  if ( !p->bReal )    {    lstrcpy( szSensKbd, p->name );	BYTE btSendType = bProcessOnDown ? QUEUE_SENSKEY_STR_OFF : p->btSendType;    ::PostMsg( q.hWnd, btSendType, (LPARAM)szSensKbd);    }  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintSensKbd(DefinePaint)  {  QueueP(Queue_SensKbd);  XFORM xf;  ::GetWorldTransform( hDC, &xf );  bool bNotDrawTransparent= ( xf.eM11 > 1. );  if ((p->nPressedCode==1)||(p->nPressedCode==0))  {	  int nStart=0x3d;	  int nEnd=0x4c;	  COLORREF clrPressed=0x333333;	  COLORREF clrTrans=0x314921;	  RECT mRectBlackWithLamp;	  if (p->bGrey)	  {		nStart=0x68;nEnd=0x94;		clrPressed=0x555555;	  }	  else	  if (p->bBlackUpWithLamp)	  {		nStart=0x30;nEnd=0x3c;		clrPressed=0x272727;		mRectBlackWithLamp=p->mRect;		mRectBlackWithLamp.left+=20;	  }	  else		  if (p->bGreen)		  {			  clrTrans=0x314921;			  clrPressed=0x2a3e1d;		  }		  else			  if (p->bRed)			  {				  clrTrans=0x00008a;				  clrPressed=0x0b0b5e;			  }	 //if (!bNotDrawTransparent)	 //{	 //if ((p->bGreen)||(p->bRed))		// ::TransparentRect( hDC, p->mRect, clrPressed, clrTrans );	 //else	 // for (int i=nStart;i<nEnd;i++)		//  if (!p->bBlackUpWithLamp)		//	::TransparentRect( hDC, p->mRect, clrPressed, RGB(i,i,i) );		//  else		//	::TransparentRect( hDC, mRectBlackWithLamp, clrPressed, RGB(i,i,i) );	 //}      CMyPen penWhite( hDC, 0xffffff,3 );	  penWhite.Rect( p->mRect );  }  if ( ::IsMnemoStyle(MNEMO_EDIT) )    {    if ( lstrcmpi( "Null", p->name ) == 0 )      {      CMyPen pen(hDC, 0xFF, 2 );      pen.Rect(p->mRect);      }    else      {      }    }  //  if ( p->bSelect )    {    if ( IsCurrentTex( q.hWnd, p->name ) )      {      //int rop2 = SetROP2( hDC, R2_XORPEN );      //::InvertRect(  hDC, &p->mRect );      //::SetROP2( hDC, rop2 );      TransparentRect( hDC, p->mRect, 0xbd3000, 0xe0e0e0 );      }    }  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddSensKbd(DefineTegs)  {  AddQueueEx(Queue_SensKbd);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_SENSKEYBOARD;  // Определение функции вывода  p->paint = &PaintSensKbd;  p->press = &PressSensKbd;  p->nPressedCode=-1;  p->bGrey=false;  p->bGreen=false;  p->bRed=false;  p->bBlackUpWithLamp=false;  //  EDirect eDir = dirFree;  //  STegObj obj[] =    {    { 'R', "rect"  , &p->mRect },    { 'E', "rc"    , &p->mRect },    { 'N', "d"     , &eDir  },    { 'N', "dir"   , &eDir  },    { 'N', "direct", &eDir  },    { 'H', "code"  , &p->nCode },    { 'L', "real"  , &p->bReal },    { 'L', "select", &p->bSelect },	{ 'B', "red", &p->bRed },	{ 'B', "grey", &p->bGrey },	{ 'B', "green", &p->bGreen },	{ 'B', "black", &p->bBlackUpWithLamp },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  StrCPY( p->name, teg[0].value, sizeof(p->name) );  //  if ( eDir != dirFree )    {    sprintf_s( def.m_szStr, 256, "<StatSensKbdX=%d,%d par0=%d par1=%d edge=1>",      p->mRect.left, p->mRect.top, p->mRect.right, p->mRect.bottom );    switch ( eDir )      {      case dirUp   :def.m_szStr[9] = 'U';break;      case dirDown :def.m_szStr[9] = 'D';break;      case dirLeft :def.m_szStr[9] = 'L';break;      case dirRight:def.m_szStr[9] = 'R';break;      }    }  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~